import {staffProjection,staffAction,can} from '../shared/team-state.js?v=5.8.0';
import {teamRead,teamChange,SAMPLE_STORAGE} from '../shared/team-storage.js?v=5.8.0';
import {expansionCopy} from '../shared/expansion-copy.js?v=5.8.0';
import {brandMark,brandLogo} from '../shared/brand.js?v=5.6.0';
import {UI} from '../shared/copy.js?v=5.6.0';
import {CHAT_COPY} from '../shared/conversation-copy.js?v=5.6.0';
import {esc,getLang,setLang,languageOptions} from '../shared/core.js?v=5.6.0';
import {tableLabel,formatBooking,partyLabel,formatMoney} from '../shared/locale.js?v=5.6.0';
const root=document.querySelector('#staff-app'),params=new URLSearchParams(location.search),role=['floor','kitchen'].includes(params.get('role'))?params.get('role'):null;
let id=params.get('member');const key=role?'one-shop-role-preview-'+role:SAMPLE_STORAGE;
let lang=getLang(),tab='ordersView',notice='';const c=()=>expansionCopy(lang),t=k=>c()[k]||CHAT_COPY[lang]?.[k]||UI[lang]?.[k]||k;
function render(){const s=role||localStorage.getItem(key)?teamRead(key):null;if(role)id=s.teamMembers.find(m=>m.role===role)?.id;const v=s?staffProjection(s,id):null;document.documentElement.lang=lang;document.title=t('demoShop');if(!v){root.innerHTML=`<main class="staff-shell"><div class="staff-invalid">${brandMark('thinking')}<p>${esc(t('revoked'))}</p><small>${esc(t('demoBoundary'))}</small></div></main>`;return;}const tabs=['ordersView','bookingsView','requestsView','menuView','salesView','settingsView'].filter(p=>can(v.member,p));if(!tabs.includes(tab))tab=tabs[0];root.innerHTML=`<main class="staff-shell"><header class="staff-top">${brandLogo()}<select id="staff-language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select></header><div class="staff-role">${brandMark(tab==='ordersView'?'order':'greeting',true)}<div><h1>${esc(t(v.member.role))}</h1><p>${esc(v.member.name)} · ${esc(v.shopName)}</p></div></div><p class="staff-note">${esc(t('demoBoundary'))}</p>${role?`<button class="staff-preview-reset" data-reset>${esc(t('resetPreview'))}</button>`:''}<nav class="staff-tabs">${tabs.map(p=>`<button data-tab="${p}" aria-pressed="${tab===p}">${esc(t(p))}</button>`).join('')}</nav><p class="team-feedback" role="status">${esc(notice)}</p><section class="staff-content">${content(v)}</section><footer class="staff-footer"><span>${esc(t('localOnly'))}</span><a href="../?lang=${lang}#team-access">${esc(t('book'))}</a></footer></main>`;}
function content(v){const m=v.member;if(tab==='ordersView')return v.orders.slice().reverse().map(o=>{const next={pending:['accepted','ordersAccept'],accepted:['preparing','ordersPrepare'],preparing:['ready','ordersPrepare'],ready:['completed','ordersServe']}[o.status];return `<article class="staff-card"><header><h2>#${o.number} · ${esc(o.channel==='online'?t('delivery'):tableLabel(o.table,lang))}</h2><span class="status">${esc(t(o.status))}</span></header>${o.lines.map(l=>`<p>${esc(l.name[lang]||l.name.ko||l.itemId)} × ${l.quantity}</p>`).join('')}${o.delivery?`<div class="staff-delivery"><small>${esc(t('deliveryAddress'))}</small><p>${esc(o.delivery.address)}</p><small>${esc(t('contact'))}</small><p>${esc(o.delivery.phone)}</p></div>`:''}${o.total!==undefined?`<p>${esc(formatMoney(o.total,lang))} · ${esc(t(o.payment))}</p>`:''}${next&&can(m,next[1])?`<button class="button primary" data-staff-order="${o.id}" data-next="${next[0]}">${esc(t(({accepted:'accept',preparing:'prepare',ready:'ready',completed:'serve'})[next[0]]))}</button>`:`<small>${esc(t('viewOnly'))}</small>`}</article>`;}).join('')||empty();
 if(tab==='bookingsView')return v.bookings.map(r=>`<article class="staff-card"><header><h2>${esc(formatBooking(r.date,r.time,lang))}</h2><span class="status">${esc(t(r.status==='confirmed'?'bookingConfirmed':r.status))}</span></header><p>${esc(r.name)} · ${esc(partyLabel(r.partySize,lang))}</p>${r.status==='pending'&&can(m,'bookingsManage')?`<button class="button" data-staff-booking="${r.id}">${esc(t('bookingAccept'))}</button>`:''}</article>`).join('')||empty();
 if(tab==='requestsView')return v.requests.map(r=>`<article class="staff-card"><h2>${esc(r.table?tableLabel(r.table,lang):t('online'))}</h2><p>${esc(r.key?t(r.key):r.text||t('requestsView'))}</p></article>`).join('')||empty();
 if(tab==='menuView')return v.items.map(i=>`<article class="staff-card"><header><h2>${esc(i.name[lang]||i.name.ko)}</h2><span class="status">${esc(t(i.available?'available':'soldOut'))}</span></header>${can(m,'menuEdit')?`<button class="button" data-staff-menu="${i.id}" data-available="${!i.available}">${esc(t(i.available?'soldOut':'available'))}</button>`:''}</article>`).join('')||empty();
 if(tab==='salesView')return `<article class="staff-card"><h2>${esc(t('salesView'))}</h2><p>${esc(formatMoney(v.sales,lang))}</p><small>${esc(t('localOnly'))}</small></article>`;
 if(tab==='settingsView')return `<article class="staff-card"><h2>${esc(v.settings.name)}</h2>${can(m,'settingsEdit')?`<form id="staff-settings"><label>${esc(t('shopPhone'))}<input name="phone" type="tel" maxlength="30" value="${esc(v.settings.phone)}" required></label><button class="button primary">${esc(t('save'))}</button></form>`:`<p>${esc(t('shopPhone'))} · ${esc(v.settings.phone)}</p>`}</article>`;
 return `<p>${esc(t('noAccess'))}</p>`;}
const empty=()=>`<p>${esc(t('noRecords'))}</p>`;
function act(action,data){try{teamChange(s=>staffAction(s,id,action,data),key);notice=t('saved');}catch(e){notice=t(e.message);}render();}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;notice='';render();}if(b.hasAttribute('data-reset')&&role){localStorage.removeItem(key);notice='';render();}if(b.dataset.staffOrder)act('order',{id:b.dataset.staffOrder,next:b.dataset.next});if(b.dataset.staffBooking)act('booking',{id:b.dataset.staffBooking});if(b.dataset.staffMenu)act('menu',{id:b.dataset.staffMenu,available:b.dataset.available==='true'});});
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='staff-settings')act('settings',{phone:new FormData(e.target).get('phone')});});
root.addEventListener('change',e=>{if(e.target.id==='staff-language'){lang=e.target.value;setLang(lang);render();}});
window.addEventListener('storage',e=>{if(e.key===key)render();});render();
